import {isMobileScreen} from './mobile.js';
import {clamp,quantize,validTarget} from './core.js';
import {wavesMarkup} from './ui.js';
import * as dialogs from './dialogs.js';
import {handleExchangeAction,previewExchange,FORMATS} from './exchange.js';
export function attachEvents(a){const $=q=>document.querySelector(q),$$=q=>Array.from(document.querySelectorAll(q));let nudge=null,jog=null,roll=null,scratchStop=null;const knobDrags=new Map();
 const fail=e=>a.toast(e.message||String(e),true);
 document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-track]');if(!el)return;try{
 if(el.dataset.mobileSurface){const i=Number(el.dataset.deck);a.s.mobile.surfaces[i]=el.dataset.mobileSurface;document.body.dataset.cueDelete='false';a.renderDeck(i);a.save();return;}
 if(el.dataset.mobileView){a.navigateMobile({view:el.dataset.mobileView});return;}if(el.hasAttribute('data-mobile-deck')){a.navigateMobile({deck:Number(el.dataset.mobileDeck)});return;}
 if(el.dataset.preset){a.layout.setPreset(el.dataset.preset);a.render();return;}if(el.dataset.panelToggle){a.layout.togglePanel(el.dataset.panelToggle);a.renderMixer();$('[data-panel=waves] .panel-body').innerHTML=wavesMarkup(a.s);return;}if(el.hasAttribute('data-layout-undo')){a.layout.undo();a.render();return;}if(el.hasAttribute('data-layout-redo')){a.layout.undo(true);a.render();return;}
 if(el.dataset.loadTrack){await a.loadDeck(Number(el.dataset.deck),el.dataset.loadTrack);if(isMobileScreen())a.navigateMobile({view:'deck'});return;}if(el.dataset.favorite){const t=a.tracks.get(el.dataset.favorite);t.rating=t.rating?0:5;await a.updateTrack(t);return;}if(el.dataset.playlist){a.s.playlist=el.dataset.playlist;a.render();a.save();return;}if(el.dataset.sort){a.sort=el.dataset.sort===a.sort.key?{...a.sort,direction:-a.sort.direction}:{key:el.dataset.sort,direction:1};a.renderRows();return;}
 if(el.hasAttribute('data-pad')){const i=Number(el.dataset.deck),j=Number(el.dataset.pad),d=a.s.decks[i];if(d.padMode==='cue')await a.hotcue(i,j,e.shiftKey||(isMobileScreen()&&document.body.dataset.cueDelete==='true'));else if(d.padMode==='jump')a.seekDeck(i,a.position(i)+[-32,-16,-8,-4,4,8,16,32][j]*60/(a.getTrack(i)?.bpm||120));return;}
 if(el.hasAttribute('data-sample')){const i=Number(el.dataset.sample);if(e.shiftKey||(isMobileScreen()&&document.body.dataset.sampleEdit==='true'))dialogs.showSampleEditor(a,i);else await a.triggerSample(i);return;}
 if(el.dataset.track){a.s.selectedTrack=el.dataset.track;a.renderRows();a.save();return;}
 const action=el.dataset.action,i=Number(el.dataset.deck),d=a.s.decks[i];if(!action)return;if(await handleExchangeAction(a,action,el))return;if(await dialogs.handleAction(a,action,el,e))return;
 switch(action){case'cue-delete':case'sample-edit':{const key=action==='cue-delete'?'cueDelete':'sampleEdit',enabled=document.body.dataset[key]!=='true';document.body.dataset[key]=String(enabled);$$('.'+action).forEach(button=>{button.classList.toggle('active',enabled);button.setAttribute('aria-pressed',enabled);});break;}case'import':$('#audio-files').click();break;case'close-dialog':a.closeModal();break;case'settings':dialogs.showSettings(a);break;case'help':dialogs.showHelp(a);break;case'midi':dialogs.showMIDI(a);break;case'layouts':dialogs.showLayouts(a);break;case'layout':a.layout.toggle();break;case'play':await a.playDeck(i);break;case'cue':await a.cue(i);break;case'sync':await a.syncDeck(i);break;case'select-deck':a.s.selectedDeck=i;a.s.decks.forEach((_,j)=>a.renderDeck(j));a.save();break;case'browse-deck':a.navigateMobile({deck:i,view:'library'});break;case'load-selected':if(a.s.selectedTrack)await a.loadDeck(i,a.s.selectedTrack);else a.toast('ライブラリで音源を選んでください。');break;case'lock':d.locked=!d.locked;a.renderDeck(i);a.save();break;case'toggle':a.toggleDeck(i,el.dataset.param);break;case'rate-reset':a.replaceValue(i,'rate',1);a.renderDeck(i);break;case'loop':a.loopDeck(i);break;case'loop-half':a.resizeLoop(i,.5);break;case'loop-double':a.resizeLoop(i,2);break;case'loop-in':d.loop.start=d.quantize?quantize(a.position(i),a.getTrack(i)?.bpm||120,a.getTrack(i)?.gridOffset||0):a.position(i);a.toast('LOOP INを設定',false,1500);a.save();break;case'loop-out':if(a.position(i)<=d.loop.start){a.toast('OUTはINより後に設定してください。',true);break;}d.loop.end=a.position(i);d.loop.enabled=true;a.engine.applyDeck(i,d,a.getTrack(i)?.bpm);a.renderDeck(i);a.save();break;case'jump':a.seekDeck(i,a.position(i)+Number(el.dataset.beats)*60/(a.getTrack(i)?.bpm||120));break;case'pad-mode':d.padMode=el.dataset.mode;a.renderDeck(i);a.save();break;case'grid':dialogs.showGrid(a,i,a.position(i));break;case'track-edit':dialogs.showTrackEditor(a,a.s.selectedTrack);break;case'new-playlist':a.modal('新しいクレート','<label><span>クレート名</span><input id="crate-name" maxlength="100" placeholder="Late night set"></label><button class="button primary" data-action="create-playlist">作成</button>');break;case'library-menu':dialogs.showLibraryMenu(a);break;case'center-crossfader':a.s.mixer.crossfader=0;a.engine.applyMixer(a.s.mixer,a.s.decks);$('#crossfader').value=0;a.save();break;case'record':await a.record();if($('#dialog').open)dialogs.showSettings(a);break;case'stop-samples':a.engine.stopSamples();break;case'zoom-in':a.zoom=clamp(a.zoom/2,2,64);$('#wave-zoom').textContent=a.zoom+'s';break;case'zoom-out':a.zoom=clamp(a.zoom*2,2,64);$('#wave-zoom').textContent=a.zoom+'s';break;}
 }catch(error){fail(error);}});
 for(const event of ['pointerdown','click'])document.addEventListener(event,e=>{if(!a.controllers.learning)return;const target=e.target.closest('[data-map]');if(!target)return;e.preventDefault();e.stopImmediatePropagation();if(event==='click'){a.controllers.arm(target.dataset.map);$$('.learning-target').forEach(el=>el.classList.remove('learning-target'));target.classList.add('learning-target');a.toast('割り当てるコントローラーのボタン・ノブを操作してください。');}},true);
 $('#audio-start').addEventListener('click',()=>a.startAudio().catch(fail));$('#audio-files').addEventListener('change',e=>{a.importFiles(e.target.files).catch(fail);e.target.value='';});
 async function onInput(e){const el=e.target;if(el.id==='exchange-format'){document.getElementById('exchange-format-note').textContent=FORMATS[el.value].note;return;}if(el.hasAttribute('data-waveform-style')){a.s.waveformStyle=el.value;$$('[data-waveform-style]').forEach(input=>input.value=el.value);a.save();const legend=document.querySelector('[data-wave-colors]');if(legend)legend.dataset.waveColors=el.value;return;}if(el.id==='track-search'){a.search=el.value;a.renderRows();return;}if(a.controllers.learning&&el.dataset.map)return;try{if(await dialogs.handleInput(a,el))return;if(el.dataset.mixer){a.s.mixer[el.dataset.mixer]=Number(el.value);$$(`[data-mixer="${el.dataset.mixer}"]`).forEach(input=>input.value=el.value);a.engine.applyMixer(a.s.mixer,a.s.decks);a.save();}else if(el.dataset.param&&el.dataset.deck!=null){a.replaceValue(Number(el.dataset.deck),el.dataset.param,el.value);a.updateParamUI(Number(el.dataset.deck),el.dataset.param,el.value);}}catch(err){fail(err);}}
 document.addEventListener('input',onInput);document.addEventListener('change',e=>{if(e.target.tagName==='SELECT')onInput(e);});
 document.addEventListener('dblclick',e=>{const tr=e.target.closest('[data-track]');if(tr&&!e.target.closest('button'))a.loadDeck(isMobileScreen()?a.s.mobile.deck:a.s.selectedDeck,tr.dataset.track).catch(fail);const knob=e.target.closest('.knob');if(knob){const input=knob.querySelector('input');a.replaceValue(Number(input.dataset.deck),input.dataset.param,0);a.updateParamUI(Number(input.dataset.deck),input.dataset.param,0);}});
 document.addEventListener('contextmenu',e=>{const pad=e.target.closest('[data-pad]'),sam=e.target.closest('[data-sample]');if(pad){e.preventDefault();a.hotcue(Number(pad.dataset.deck),Number(pad.dataset.pad),true).catch(fail);}if(sam){e.preventDefault();dialogs.showSampleEditor(a,Number(sam.dataset.sample));}});
 document.addEventListener('pointerdown',e=>{if(a.layout.editing||a.controllers.learning||e.button!==0)return;const knob=e.target.closest('.knob'),wheel=e.target.closest('[data-jog]'),over=e.target.closest('[data-overview]'),nud=e.target.closest('[data-nudge]'),pad=e.target.closest('[data-pad]');
 if(knob){const input=knob.querySelector('input[type=range]');if(input){e.preventDefault();input.setPointerCapture(e.pointerId);knobDrags.set(e.pointerId,{input,i:Number(input.dataset.deck),key:input.dataset.param,x:e.clientX,y:e.clientY,value:Number(input.value),min:Number(input.min),max:Number(input.max)});}}
 if(over){const i=Number(over.dataset.overview),r=over.getBoundingClientRect();a.seekDeck(i,(e.clientX-r.left)/r.width*(a.getTrack(i)?.duration||0));}
 if(wheel){const i=Number(wheel.dataset.jog);if(!a.engine.has(a.s.decks[i].trackId)){a.toast('一度再生するとジョグを使えます。');return;}e.preventDefault();wheel.setPointerCapture(e.pointerId);jog={i,id:e.pointerId,x:e.clientX,t:e.timeStamp};a.engine.scratch(i,true,0);}
 if(nud){const i=Number(nud.dataset.deck);e.preventDefault();nud.setPointerCapture(e.pointerId);nudge={i,id:e.pointerId};a.engine.applyDeck(i,{...a.s.decks[i],rate:a.s.decks[i].rate*(1+Number(nud.dataset.nudge)*.035)},a.getTrack(i)?.bpm);}
 if(pad&&a.s.decks[Number(pad.dataset.deck)].padMode==='roll'){const i=Number(pad.dataset.deck),t=a.getTrack(i);if(!t||!a.s.decks[i].playing)return;const beats=[.125,.25,.5,1,2,4,8,16][Number(pad.dataset.pad)],start=quantize(a.position(i),t.bpm,t.gridOffset);e.preventDefault();pad.setPointerCapture(e.pointerId);pad.classList.add('pressed');roll={i,id:e.pointerId,el:pad};a.engine.roll(i,true,start,Math.min(t.duration,start+beats*60/t.bpm));}
 });
 document.addEventListener('pointermove',e=>{const k=knobDrags.get(e.pointerId);if(k){e.preventDefault();const value=clamp(k.value+((e.clientX-k.x)-(e.clientY-k.y))*(k.max-k.min)/120,k.min,k.max);a.replaceValue(k.i,k.key,value);k.input.value=value;a.updateParamUI(k.i,k.key,value);}if(jog&&e.pointerId===jog.id){const dt=Math.max(1,e.timeStamp-jog.t),speed=clamp((e.clientX-jog.x)/dt*3,-8,8);jog.x=e.clientX;jog.t=e.timeStamp;a.engine.scratch(jog.i,true,speed);clearTimeout(scratchStop);scratchStop=setTimeout(()=>{if(jog)a.engine.scratch(jog.i,true,0);},80);}});
 function release(e){if(e)knobDrags.delete(e.pointerId);else knobDrags.clear();if(jog&&(!e||jog.id===e.pointerId)){clearTimeout(scratchStop);a.engine.scratch(jog.i,false);jog=null;a.save();}if(nudge&&(!e||nudge.id===e.pointerId)){a.engine.applyDeck(nudge.i,a.s.decks[nudge.i],a.getTrack(nudge.i)?.bpm);nudge=null;}if(roll&&(!e||roll.id===e.pointerId)){a.engine.roll(roll.i,false);roll.el.classList.remove('pressed');roll=null;a.save();}}
 document.addEventListener('pointerup',release);document.addEventListener('pointercancel',release);document.addEventListener('lostpointercapture',release);window.addEventListener('resize',()=>release());window.addEventListener('blur',()=>release());
 document.addEventListener('dragstart',e=>{const tr=e.target.closest('[data-track]');if(!tr)return;e.dataTransfer.setData('application/x-orbit-track',tr.dataset.track);e.dataTransfer.effectAllowed='copy';});
 document.addEventListener('dragover',e=>{if(!Array.from(e.dataTransfer.types).some(t=>t==='Files'||t==='application/x-orbit-track'))return;e.preventDefault();const target=e.target.closest('[data-panel^=deck],[data-sample]');$$('.drop-target').forEach(x=>{if(x!==target)x.classList.remove('drop-target');});target?.classList.add('drop-target');});
 document.addEventListener('dragleave',e=>{if(!e.relatedTarget)$$('.drop-target').forEach(x=>x.classList.remove('drop-target'));});
 document.addEventListener('drop',async e=>{e.preventDefault();$$('.drop-target').forEach(x=>x.classList.remove('drop-target'));try{if(e.dataTransfer.files.length){await a.importFiles(e.dataTransfer.files);return;}const id=e.dataTransfer.getData('application/x-orbit-track');if(!id)return;const sample=e.target.closest('[data-sample]'),deck=e.target.closest('[data-panel^=deck]');if(sample){const t=a.tracks.get(id);await a.setSample(Number(sample.dataset.sample),{trackId:id,label:t.name,start:0,duration:Math.min(8*60/t.bpm,t.duration,30),gain:.8,loop:false});}else if(deck)await a.loadDeck(Number(deck.dataset.panel.slice(4)),id);}catch(err){fail(err);}});
 document.addEventListener('keydown',e=>{if(e.repeat||e.altKey||e.metaKey||e.ctrlKey){if((e.ctrlKey||e.metaKey)&&e.code==='KeyZ'&&a.layout.editing&&!$('#dialog').open){e.preventDefault();a.layout.undo(e.shiftKey);a.render();}return;}if($('#dialog').open||/INPUT|SELECT|TEXTAREA|BUTTON/.test(e.target.tagName)||e.target.isContentEditable)return;const wheel=e.target.closest('[data-jog],[data-overview]');if(wheel&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const i=Number(wheel.dataset.jog??wheel.dataset.overview);a.seekDeck(i,e.key==='Home'?0:e.key==='End'?a.getTrack(i)?.duration:a.position(i)+(e.key==='ArrowRight'?1:-1)*(e.shiftKey?5:.1));return;}const track=e.target.closest('[data-track]');if(track&&e.key==='Enter'){e.preventDefault();a.loadDeck(a.s.selectedDeck,track.dataset.track).catch(fail);return;}const map={Space:['play',a.s.selectedDeck],KeyQ:['play',0],KeyW:['cue',0],KeyU:['play',1],KeyI:['cue',1]};let job;if(map[e.code]){e.preventDefault();const [key,i]=map[e.code];job=key==='play'?a.playDeck(i):a.cue(i);}else{const ai=['Digit1','Digit2','Digit3','Digit4'].indexOf(e.code),bi=['Digit6','Digit7','Digit8','Digit9'].indexOf(e.code);if(ai>=0||bi>=0){e.preventDefault();job=a.hotcue(ai>=0?0:1,ai>=0?ai:bi,e.shiftKey);}}job?.catch(fail);});
 a.controllers.addEventListener('mapped',()=>{a.save();$$('.learning-target').forEach(x=>x.classList.remove('learning-target'));a.toast('MIDI割り当てを保存しました。');if($('#dialog').open)dialogs.showMIDI(a);});a.controllers.addEventListener('input',e=>{if($('#midi-monitor'))$('#midi-monitor').textContent=e.detail;});a.controllers.addEventListener('hid-input',e=>{if($('#hid-monitor'))$('#hid-monitor').textContent=e.detail;});a.controllers.addEventListener('devices',()=>{$('#midi-status').textContent=a.controllers.access?`MIDI · ${Array.from(a.controllers.access.inputs.values()).filter(x=>x.state==='connected').length}`:'MIDI';if($('#dialog').open&&$('#midi-monitor'))dialogs.showMIDI(a);});
 $('#json-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>25*1024*1024)throw new Error('JSONファイルは25 MB以下にしてください。');const raw=JSON.parse(await file.text());if(a.jsonPurpose==='session')await a.restoreSession(raw);else if(a.jsonPurpose==='midi'){const list=raw.midiMappings||raw.mappings;if(!Array.isArray(list))throw new Error('midiMappings配列がありません。');a.s.midiMappings=list.filter(m=>validTarget(m.target)&&['cc','note','pitchbend'].includes(m.kind)&&Number.isInteger(m.channel)&&m.channel>=0&&m.channel<16&&Number.isInteger(m.number)&&m.number>=0&&m.number<128).slice(0,1000);a.save();dialogs.showMIDI(a);a.toast('MIDIマッピングを読み込みました。');}else if(a.jsonPurpose==='hid'){const list=raw.hidMappings;if(!Array.isArray(list))throw new Error('hidMappings配列がありません。');a.s.hidMappings=list.filter(m=>validTarget(m.target)&&Number.isInteger(m.vendorId)&&Number.isInteger(m.productId)&&Number.isInteger(m.reportId)&&Number.isInteger(m.offset)).slice(0,1000);a.save();dialogs.showMIDI(a);a.toast('HIDプロファイルを読み込みました。');}}catch(err){fail(err);}});
 $('#exchange-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{await previewExchange(a,file);}catch(err){fail(err);}});
 $('#audio-folder').addEventListener('change',e=>{a.importFiles(e.target.files).catch(fail);e.target.value='';});
}
